pg_continuous_archiving:
{
  "steps": [
    {
      "step_id": "S1",
      "source_lines": [40],
      "source_quote": "To enable WAL archiving, set the wal_level configuration parameter to replica or higher, archive_mode to on, specify the shell command to use in the archive_command configuration parameter or specify the library to use in the archive_library configuration parameter.",
      "tote": {
        "initial_test": "Check if wal_level >= replica, archive_mode = on, and archive_command/archive_library are configured.",
        "operate": "Update postgresql.conf with required parameters.",
        "exit": "Verify configuration settings are applied.",
        "max_iterations": 1
      },
      "exit_checks": [
        {
          "type": "human_review",
          "params": {},
          "basis": "human_judgement"
        }
      ]
    },
    {
      "step_id": "S2",
      "source_lines": [53, 54, 55],
      "source_quote": "It is important that the archive command return zero exit status if and only if it succeeds. Upon getting a zero result, PostgreSQL will assume that the file has been successfully archived, and will remove or recycle it. However, a nonzero status tells PostgreSQL that the file was not archived; it will try again periodically until it succeeds.",
      "tote": {
        "initial_test": "Check if archive command returns zero exit status.",
        "operate": "Execute archive command.",
        "exit": "Verify exit status is 0.",
        "max_iterations": 10
      },
      "exit_checks": [
        {
          "type": "exit_code_equals",
          "params": {
            "value": 0
          },
          "basis": "source_stated"
        }
      ]
    },
    {
      "step_id": "S3",
      "source_lines": [64],
      "source_quote": "It is advisable to test your proposed archive library to ensure that it does not overwrite an existing file.",
      "tote": {
        "initial_test": "Check if archive command/library overwrites existing files.",
        "operate": "Run archive command with a pre-existing file in the destination.",
        "exit": "Verify file is not overwritten and command returns appropriate status.",
        "max_iterations": 1
      },
      "exit_checks": [
        {
          "type": "human_review",
          "params": {},
          "basis": "human_judgement"
        }
      ]
    }
  ]
}

